import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { newDbPath, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
}

async function createTask(server: Running, title: string): Promise<Task> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  assert.equal(response.status, 201);
  return ((await response.json()) as { task: Task }).task;
}

async function listTasks(server: Running): Promise<Task[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  return ((await response.json()) as { tasks: Task[] }).tasks;
}

function deleteTask(server: Running, id: number | string): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks/${id}`, { method: "DELETE" });
}

describe("SL-006 delete a task permanently", () => {
  describe("AC-1: an existing task is deleted", () => {
    const dbPath = newDbPath();
    let server: Running | undefined;

    after(async () => {
      await server?.stop();
    });

    it("AC-1: DELETE answers 204 and the task leaves the list, the others stay", async () => {
      server = await startServer(dbPath);
      const doomed = await createTask(server, "Buy milk");
      const kept = await createTask(server, "Walk the dog");

      const response = await deleteTask(server, doomed.id);
      assert.equal(response.status, 204);
      assert.equal(await response.text(), "");

      const tasks = await listTasks(server);
      assert.deepEqual(
        tasks.map((t) => t.id),
        [kept.id],
      );
    });

    it("AC-1: the deleted task does not return after kill -9 and a restart", async () => {
      await server?.stop();
      server = await startServer(dbPath);

      const tasks = await listTasks(server);
      assert.deepEqual(
        tasks.map((t) => t.title),
        ["Walk the dog"],
      );
    });
  });

  describe("AC-1: the page asks for a browser confirmation before it deletes", () => {
    let html: string;
    let script: string;
    let server: Running;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: app.js sends DELETE to /api/tasks/:id only after window.confirm", () => {
      assert.match(script, /method:\s*["']DELETE["']/);
      assert.match(script, /\/api\/tasks\/\$\{/);
      const confirmAt = script.indexOf("confirm(");
      const deleteAt = script.search(/method:\s*["']DELETE["']/);
      assert.ok(confirmAt >= 0 && confirmAt < deleteAt, "confirm() comes before the DELETE request");
      assert.doesNotMatch(script, /innerHTML/);
    });

    it("AC-1: the page still serves the task list element", () => {
      assert.match(html, /<ul[^>]+id=["']task-list["']/);
    });
  });

  describe("AC-2: a task that does not exist", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: DELETE of an unknown id answers 404 not_found", async () => {
      const response = await deleteTask(server, 999);
      assert.equal(response.status, 404);
      const body = (await response.json()) as { error: { code: string; message: string } };
      assert.equal(body.error.code, "not_found");
      assert.equal(typeof body.error.message, "string");
    });

    it("AC-2: deleting the same task twice answers 204 then 404", async () => {
      const task = await createTask(server, "Once only");
      assert.equal((await deleteTask(server, task.id)).status, 204);
      assert.equal((await deleteTask(server, task.id)).status, 404);
    });

    it("AC-2: a non-numeric id answers 404 and deletes nothing", async () => {
      const task = await createTask(server, "Survivor");
      for (const id of ["abc", "1.5", "-1", "1abc"]) {
        assert.equal((await deleteTask(server, id)).status, 404, id);
      }
      assert.ok((await listTasks(server)).some((t) => t.id === task.id));
    });
  });
});
EOF
